/// Integration tests for the CRUD operations available in `Canyon` that
/// generates and executes *SELECT* statements based on an entity
/// annotated with the `#[foreign_key(... args)]` annotation looking
/// for related data through an entity `U` that acts as its parent.
///
/// Names of the foreign key methods are autogenerated for the direct and
/// reverse side of the implementations.
#[cfg(feature = "mysql")]
use crate::constants::MYSQL_DS;
#[cfg(feature = "postgres")]
use crate::constants::PSQL_DS;
#[cfg(feature = "mssql")]
use crate::constants::SQL_SERVER_DS;

use crate::tests_models::league::*;
use crate::tests_models::tournament::*;
use crate::tests_models::tournament_details::TournamentDetails;
use crate::tests_models::tournament_entry::TournamentEntry;
use crate::tests_models::tournament_organizer::TournamentOrganizer;

use canyon_sql::{CanyonResult, connection::DbConnection, crud::Read};

#[cfg(feature = "postgres")]
const POSTGRES_RELATIONSHIP_TABLES: &[&str] = &[
    "CREATE TABLE IF NOT EXISTS public.tournament_details (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, external_id BIGINT NOT NULL UNIQUE, description TEXT NOT NULL)",
    "CREATE TABLE IF NOT EXISTS public.tournament_organizers (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, external_id BIGINT NOT NULL UNIQUE, name TEXT NOT NULL)",
    "CREATE TABLE IF NOT EXISTS public.tournament_entries (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, details_id BIGINT NOT NULL REFERENCES public.tournament_details(external_id), organizer_id BIGINT NOT NULL REFERENCES public.tournament_organizers(external_id), label TEXT NOT NULL)",
];

#[cfg(feature = "mysql")]
const MYSQL_RELATIONSHIP_TABLES: &[&str] = &[
    "CREATE TABLE IF NOT EXISTS public.tournament_details (id INT AUTO_INCREMENT PRIMARY KEY, external_id BIGINT NOT NULL UNIQUE, description TEXT NOT NULL)",
    "CREATE TABLE IF NOT EXISTS public.tournament_organizers (id INT AUTO_INCREMENT PRIMARY KEY, external_id BIGINT NOT NULL UNIQUE, name TEXT NOT NULL)",
    "CREATE TABLE IF NOT EXISTS public.tournament_entries (id INT AUTO_INCREMENT PRIMARY KEY, details_id BIGINT NOT NULL, organizer_id BIGINT NOT NULL, label TEXT NOT NULL, FOREIGN KEY (details_id) REFERENCES tournament_details(external_id), FOREIGN KEY (organizer_id) REFERENCES tournament_organizers(external_id))",
];

#[cfg(feature = "mssql")]
const MSSQL_RELATIONSHIP_TABLES: &[&str] = &[
    "IF OBJECT_ID(N'dbo.tournament_details', N'U') IS NULL CREATE TABLE dbo.tournament_details (id INT IDENTITY PRIMARY KEY, external_id BIGINT NOT NULL UNIQUE, description NVARCHAR(250) NOT NULL)",
    "IF OBJECT_ID(N'dbo.tournament_organizers', N'U') IS NULL CREATE TABLE dbo.tournament_organizers (id INT IDENTITY PRIMARY KEY, external_id BIGINT NOT NULL UNIQUE, name NVARCHAR(250) NOT NULL)",
    "IF OBJECT_ID(N'dbo.tournament_entries', N'U') IS NULL CREATE TABLE dbo.tournament_entries (id INT IDENTITY PRIMARY KEY, details_id BIGINT NOT NULL REFERENCES dbo.tournament_details(external_id), organizer_id BIGINT NOT NULL REFERENCES dbo.tournament_organizers(external_id), label NVARCHAR(250) NOT NULL)",
];

/// Keep the fixture local to these tests so persistent Docker volumes do not
/// depend on the entrypoint initialization scripts being rerun.
async fn prepare_relationship_fixture(
    datasource: &str,
    schema: &str,
    create_tables: &[&str],
) -> CanyonResult<()> {
    for statement in create_tables {
        datasource.execute(statement, &[]).await?;
    }

    let details = format!("{schema}.tournament_details");
    let organizers = format!("{schema}.tournament_organizers");
    let entries = format!("{schema}.tournament_entries");

    for (external_id, description) in [(9001, "Spring split"), (9002, "Summer split")] {
        let statement = format!(
            "INSERT INTO {details} (external_id, description) SELECT {external_id}, '{description}' WHERE NOT EXISTS (SELECT 1 FROM {details} WHERE external_id = {external_id})"
        );
        datasource.execute(&statement, &[]).await?;
    }

    for (external_id, name) in [(7001, "North organizer"), (7002, "South organizer")] {
        let statement = format!(
            "INSERT INTO {organizers} (external_id, name) SELECT {external_id}, '{name}' WHERE NOT EXISTS (SELECT 1 FROM {organizers} WHERE external_id = {external_id})"
        );
        datasource.execute(&statement, &[]).await?;
    }

    for (details_id, organizer_id, label) in [
        (9001, 7001, "alpha"),
        (9001, 7001, "beta"),
        (9002, 7002, "gamma"),
    ] {
        let statement = format!(
            "INSERT INTO {entries} (details_id, organizer_id, label) SELECT {details_id}, {organizer_id}, '{label}' WHERE NOT EXISTS (SELECT 1 FROM {entries} WHERE details_id = {details_id} AND organizer_id = {organizer_id} AND label = '{label}')"
        );
        datasource.execute(&statement, &[]).await?;
    }

    Ok(())
}

fn alpha_entry(entries: Vec<TournamentEntry>) -> TournamentEntry {
    entries
        .into_iter()
        .find(|entry| {
            entry.details_id == 9001 && entry.organizer_id == 7001 && entry.label == "alpha"
        })
        .expect("the relationship fixture is missing its alpha entry")
}

fn assert_details_parent(entry: &TournamentEntry, parent: &TournamentDetails) {
    assert_eq!(entry.details_id, parent.external_id);
    assert_eq!(parent.external_id, 9001);
    assert_eq!(parent.description, "Spring split");
}

fn assert_details_children(parent: &TournamentDetails, mut children: Vec<TournamentEntry>) {
    children.sort_by_key(|entry| entry.id);

    assert_eq!(children.len(), 2);
    assert!(
        children
            .iter()
            .all(|entry| entry.details_id == parent.external_id)
    );
    assert_eq!(children[0].label, "alpha");
    assert_eq!(children[1].label, "beta");
}

fn assert_organizer_parent(entry: &TournamentEntry, parent: &TournamentOrganizer) {
    assert_eq!(entry.organizer_id, parent.external_id);
    assert_eq!(parent.external_id, 7001);
    assert_eq!(parent.name, "North organizer");
}

fn assert_organizer_children(parent: &TournamentOrganizer, mut children: Vec<TournamentEntry>) {
    children.sort_by_key(|entry| entry.id);

    assert_eq!(children.len(), 2);
    assert!(
        children
            .iter()
            .all(|entry| entry.organizer_id == parent.external_id)
    );
    assert_eq!(children[0].label, "alpha");
    assert_eq!(children[1].label, "beta");
}

/// Given an entity `T` which has some field declaring a foreign key relation
/// with some another entity `U`, for example, performs a search to find
/// what is the parent type `U` of `T`
#[cfg(feature = "postgres")]
#[canyon_sql::macros::canyon_tokio_test]
fn test_crud_search_by_foreign_key() {
    let some_tournament: Tournament = Tournament::find_by_pk(&1)
        .await
        .expect("Result variant of the query is err")
        .expect("No result found for the given parameter");

    // We can get the parent entity for the retrieved child instance
    let league: League = some_tournament
        .find_league()
        .await
        .expect("failed to find the PostgreSQL tournament's league")
        .expect("the seeded PostgreSQL tournament must have a league");
    assert_eq!(some_tournament.league, league.id);

    let mut tournament_without_league = some_tournament;
    tournament_without_league.league = i32::MAX;
    assert!(
        tournament_without_league
            .find_league()
            .await
            .expect("failed to check a missing PostgreSQL league")
            .is_none()
    );
}

