/// Exercises the complete relationship API against PostgreSQL while also
/// proving default compound table names, custom child table names, qualified
/// Rust paths and references to non-primary-key columns.
#[cfg(feature = "postgres")]
#[canyon_sql::macros::canyon_tokio_test]
fn test_compound_and_custom_table_relationships_postgres() {
    prepare_relationship_fixture(PSQL_DS, "public", POSTGRES_RELATIONSHIP_TABLES)
        .await
        .expect("failed to prepare the PostgreSQL relationship fixture");

    let entry = TournamentEntry::find_all()
        .await
        .map(alpha_entry)
        .expect("failed to query the PostgreSQL relationship fixture");

    let parent = entry
        .find_details()
        .await
        .expect("failed to follow the default PostgreSQL relationship")
        .expect("the PostgreSQL relationship parent is missing");
    assert_details_parent(&entry, &parent);

    let parent_with = entry
        .find_details_with(PSQL_DS)
        .await
        .expect("failed to follow the explicit PostgreSQL relationship")
        .expect("the explicit PostgreSQL relationship parent is missing");
    assert_details_parent(&entry, &parent_with);

    let children = TournamentEntry::find_all_by_details(&parent)
        .await
        .expect("failed to query the reverse PostgreSQL relationship");
    assert_details_children(&parent, children);

    let children_with = TournamentEntry::find_all_by_details_with(&parent, PSQL_DS)
        .await
        .expect("failed to query the explicit reverse PostgreSQL relationship");
    assert_details_children(&parent, children_with);

    let organizer = entry
        .find_organizer()
        .await
        .expect("failed to follow the custom-table PostgreSQL relationship")
        .expect("the custom-table PostgreSQL relationship parent is missing");
    assert_organizer_parent(&entry, &organizer);

    let organizer_with = entry
        .find_organizer_with(PSQL_DS)
        .await
        .expect("failed to follow the explicit custom-table PostgreSQL relationship")
        .expect("the explicit custom-table PostgreSQL parent is missing");
    assert_organizer_parent(&entry, &organizer_with);

    let organized_entries = TournamentEntry::find_all_by_organizer(&organizer)
        .await
        .expect("failed to query the reverse custom-table PostgreSQL relationship");
    assert_organizer_children(&organizer, organized_entries);

    let organized_entries_with = TournamentEntry::find_all_by_organizer_with(&organizer, PSQL_DS)
        .await
        .expect("failed to query the explicit reverse custom-table PostgreSQL relationship");
    assert_organizer_children(&organizer, organized_entries_with);
}

/// Exercises both datasource-explicit relationship directions against SQL
/// Server using the same non-trivial mapping fixture as PostgreSQL.
#[cfg(feature = "mssql")]
#[canyon_sql::macros::canyon_tokio_test]
fn test_compound_and_custom_table_relationships_mssql() {
    prepare_relationship_fixture(SQL_SERVER_DS, "dbo", MSSQL_RELATIONSHIP_TABLES)
        .await
        .expect("failed to prepare the SQL Server relationship fixture");

    let entry = TournamentEntry::find_all_with(SQL_SERVER_DS)
        .await
        .map(alpha_entry)
        .expect("failed to query the SQL Server relationship fixture");

    let parent = entry
        .find_details_with(SQL_SERVER_DS)
        .await
        .expect("failed to follow the SQL Server relationship")
        .expect("the SQL Server relationship parent is missing");
    assert_details_parent(&entry, &parent);

    let children = TournamentEntry::find_all_by_details_with(&parent, SQL_SERVER_DS)
        .await
        .expect("failed to query the reverse SQL Server relationship");
    assert_details_children(&parent, children);

    let organizer = entry
        .find_organizer_with(SQL_SERVER_DS)
        .await
        .expect("failed to follow the custom-table SQL Server relationship")
        .expect("the custom-table SQL Server relationship parent is missing");
    assert_organizer_parent(&entry, &organizer);

    let organized_entries = TournamentEntry::find_all_by_organizer_with(&organizer, SQL_SERVER_DS)
        .await
        .expect("failed to query the reverse custom-table SQL Server relationship");
    assert_organizer_children(&organizer, organized_entries);
}

